package br.edu.cs.poo.ac.seguro.entidades;
import java.io.Serializable; import java.math.BigDecimal;
public class Apolice implements Serializable { private static final long serialVersionUID=1L; private Veiculo veiculo; private BigDecimal valorFranquia,valorPremio,valorMaximoSegurado; public Apolice(Veiculo veiculo,BigDecimal valorFranquia,BigDecimal valorPremio,BigDecimal valorMaximoSegurado){this.veiculo=veiculo;this.valorFranquia=valorFranquia;this.valorPremio=valorPremio;this.valorMaximoSegurado=valorMaximoSegurado;} public Veiculo getVeiculo(){return veiculo;} public void setVeiculo(Veiculo v){veiculo=v;} public BigDecimal getValorFranquia(){return valorFranquia;} public void setValorFranquia(BigDecimal v){valorFranquia=v;} public BigDecimal getValorPremio(){return valorPremio;} public void setValorPremio(BigDecimal v){valorPremio=v;} public BigDecimal getValorMaximoSegurado(){return valorMaximoSegurado;} public void setValorMaximoSegurado(BigDecimal v){valorMaximoSegurado=v;} }
